UserScriptDialog::UserScriptDialog(QString interpreter,QString manifest,QString folder,QStringList selection,QWidget *parent):QDialog(parent),m_folder(std::move(folder)),m_selection(std::move(selection)){
    setObjectName("userScriptDialog");setWindowTitle(tr("Scripts e formulários"));resize(1050,800);auto *layout=new QVBoxLayout(this);auto *hint=new QLabel(tr("Carregue um formulário e confira o código. Cada execução usa a cópia exata exibida, com suas permissões de usuário para arquivos, programas e rede. Não há isolamento. O processo e seus auxiliares supervisionados podem ser cancelados; alterações já feitas são preservadas. Carregar o formulário não executa código. Valores e saída ficam somente nesta janela."),this);hint->setWordWrap(true);layout->addWidget(hint);auto *form=new QFormLayout;layout->addLayout(form);
    auto path=[&](const QString &label,const QString &value,const char *name,bool executable){auto *row=new QHBoxLayout;auto *field=new QLineEdit(value,this);field->setObjectName(name);field->setMaxLength(32767);auto *choose=new QPushButton(tr("Escolher…"),this);m_pathChoices.append(choose);row->addWidget(field);row->addWidget(choose);form->addRow(label,row);connect(choose,&QPushButton::clicked,this,[this,field,executable]{const auto value=QFileDialog::getOpenFileName(this,executable?tr("Interpretador Python instalado"):tr("Formulário de script"),field->text(),executable?"Programas (*.exe)":"Formulário DirOpen (*.json)");if(!value.isEmpty())field->setText(value);});return field;};
    if(interpreter.isEmpty()&&QFileInfo("C:/Python314/python.exe").isFile())interpreter="C:/Python314/python.exe";m_interpreter=path(tr("Python:"),interpreter,"scriptInterpreter",true);m_manifest=path(tr("Formulário:"),manifest,"scriptManifest",false);m_load=new QPushButton(tr("Carregar formulário"),this);m_load->setObjectName("loadUserScript");form->addRow(m_load);m_identity=new QLabel(tr("Nenhum código carregado."),this);m_identity->setObjectName("scriptIdentity");m_identity->setWordWrap(true);m_identity->setTextFormat(Qt::PlainText);m_identity->setTextInteractionFlags(Qt::TextSelectableByMouse);layout->addWidget(m_identity);
    auto *tabs=new QTabWidget(this);tabs->setObjectName("scriptTabs");layout->addWidget(tabs,1);m_form=new QScrollArea(this);m_form->setWidgetResizable(true);m_form->setObjectName("scriptForm");tabs->addTab(m_form,tr("Formulário"));m_code=new QPlainTextEdit(this);m_code->setObjectName("scriptCode");m_code->setReadOnly(true);m_code->setLineWrapMode(QPlainTextEdit::NoWrap);tabs->addTab(m_code,tr("Código aprovado"));auto *context=new QPlainTextEdit(this);context->setReadOnly(true);QString selected;for(const auto &p:m_selection){if(selected.size()+p.size()>65536){selected+=tr("\n[Exibição de locais limitada a 64 mil caracteres.]");break;}selected+=p+'\n';}context->setPlainText(tr("Pasta de trabalho: %1\nSeleção: %2 itens\n\n%3").arg(m_folder).arg(m_selection.size()).arg(selected));tabs->addTab(context,tr("Pasta e seleção"));m_output=new QPlainTextEdit(this);m_output->setObjectName("scriptOutput");m_output->setReadOnly(true);tabs->addTab(m_output,tr("Saída"));
    m_status=new QLabel(tr("Escolha um formulário JSON e carregue para revisar."),this);m_status->setObjectName("scriptStatus");m_status->setWordWrap(true);m_status->setTextFormat(Qt::PlainText);m_status->setTextInteractionFlags(Qt::TextSelectableByMouse);layout->addWidget(m_status);m_permission=new QCheckBox(tr("Autorizo esta execução do código exibido com minhas permissões de usuário."),this);m_permission->setObjectName("scriptPermission");layout->addWidget(m_permission);auto *buttons=new QHBoxLayout;layout->addLayout(buttons);m_run=new QPushButton(tr("Revisar e executar…"),this);m_run->setObjectName("runUserScript");m_run->setAutoDefault(false);m_cancel=new QPushButton(tr("Cancelar execução"),this);m_cancel->setObjectName("cancelUserScript");buttons->addWidget(m_run);buttons->addWidget(m_cancel);buttons->addStretch();auto *close=new QPushButton(tr("Fechar"),this);buttons->addWidget(close);connect(close,&QPushButton::clicked,this,&UserScriptDialog::reject);connect(m_load,&QPushButton::clicked,this,&UserScriptDialog::load);connect(m_run,&QPushButton::clicked,this,&UserScriptDialog::run);connect(m_permission,&QCheckBox::toggled,this,&UserScriptDialog::updatePermission);connect(m_interpreter,&QLineEdit::textChanged,this,[this]{m_permission->setChecked(false);});connect(m_manifest,&QLineEdit::textChanged,this,&UserScriptDialog::clearScript);connect(m_cancel,&QPushButton::clicked,this,[this]{if(m_job){m_job->cancel();m_cancel->setEnabled(false);m_status->setText(tr("Aguardando o script e os auxiliares supervisionados encerrarem…"));}});clearScript();setBusy(false);
}
UserScriptDialog::~UserScriptDialog(){if(m_job){m_job->cancel();m_job->wait();}}
QString UserScriptDialog::interpreter()const{return QDir::fromNativeSeparators(m_interpreter->text().trimmed());}
QString UserScriptDialog::manifest()const{return QDir::fromNativeSeparators(m_manifest->text().trimmed());}
void UserScriptDialog::clearScript(){if(m_job)return;m_script.reset();m_fields.clear();delete m_form->takeWidget();m_form->setWidget(new QWidget(m_form));m_code->clear();m_output->clear();m_status->setText(tr("Carregue o formulário para revisar o código."));m_permission->setChecked(false);m_identity->setText(tr("Nenhum código carregado."));updatePermission();}
void UserScriptDialog::load(){
    if(m_job)return;clearScript();const auto loaded=readUserScript(manifest());if(!loaded.script){m_status->setText(loaded.error);return;}m_script=loaded.script;auto *body=new QWidget;auto *form=new QFormLayout(body);const auto changed=[this]{m_permission->setChecked(false);};
    for(const auto &field:m_script->fields){QWidget *widget=nullptr;if(field.type==ScriptFieldType::Boolean){auto *value=new QCheckBox(body);value->setChecked(field.initial.toBool());connect(value,&QCheckBox::toggled,this,changed);widget=value;}else if(field.type==ScriptFieldType::Integer){auto *value=new QSpinBox(body);value->setRange(field.minimum,field.maximum);value->setValue(field.initial.toInt());connect(value,&QSpinBox::valueChanged,this,changed);widget=value;}else if(field.type==ScriptFieldType::Choice){auto *value=new QComboBox(body);value->addItems(field.choices);value->setCurrentText(field.initial.toString());connect(value,&QComboBox::currentTextChanged,this,changed);widget=value;}else{auto *value=new QLineEdit(field.initial.toString(),body);value->setMaxLength(field.maxLength);connect(value,&QLineEdit::textChanged,this,changed);widget=value;}
        widget->setObjectName("scriptField_"+field.id);m_fields[field.id]=widget;auto *label=new QLabel(field.label+(field.required?" *":QString{}),body);label->setTextFormat(Qt::PlainText);label->setWordWrap(true);if(field.type==ScriptFieldType::File||field.type==ScriptFieldType::Folder){auto *row=new QWidget(body);auto *box=new QHBoxLayout(row);box->setContentsMargins(0,0,0,0);auto *browse=new QPushButton(tr("Escolher…"),row);box->addWidget(widget);box->addWidget(browse);form->addRow(label,row);connect(browse,&QPushButton::clicked,this,[this,value=static_cast<QLineEdit*>(widget),type=field.type]{const auto selected=type==ScriptFieldType::File?QFileDialog::getOpenFileName(this,tr("Arquivo de entrada"),value->text()):QFileDialog::getExistingDirectory(this,tr("Pasta"),value->text());if(!selected.isEmpty())value->setText(selected);});}else form->addRow(label,widget);
    }
    delete m_form->takeWidget();m_form->setWidget(body);m_code->setPlainText(QString::fromUtf8(m_script->source));m_identity->setText(m_script->title+"\n"+m_script->description+"\nSHA-256: "+QString::fromLatin1(m_script->digest.toHex()));m_status->setText(tr("Formulário carregado; nenhum código executado. Confira o código e os campos antes de autorizar."));updatePermission();
}
QJsonObject UserScriptDialog::values()const{QJsonObject result;if(!m_script)return result;for(const auto &field:m_script->fields){auto *widget=m_fields.value(field.id);if(field.type==ScriptFieldType::Boolean)result[field.id]=static_cast<QCheckBox*>(widget)->isChecked();else if(field.type==ScriptFieldType::Integer)result[field.id]=static_cast<QSpinBox*>(widget)->value();else if(field.type==ScriptFieldType::Choice)result[field.id]=static_cast<QComboBox*>(widget)->currentText();else result[field.id]=static_cast<QLineEdit*>(widget)->text();}return result;}
void UserScriptDialog::updatePermission(){m_run->setEnabled(!m_job&&m_script.has_value()&&m_permission->isChecked());}
void UserScriptDialog::setBusy(bool busy){for(auto *button:m_pathChoices)button->setEnabled(!busy);m_interpreter->setEnabled(!busy);m_manifest->setEnabled(!busy);m_load->setEnabled(!busy);m_form->setEnabled(!busy);m_permission->setEnabled(!busy);m_cancel->setEnabled(busy);updatePermission();}
void UserScriptDialog::run(){
    if(m_job||!m_script||!m_permission->isChecked())return;const auto execution=prepareScriptExecution(*m_script,interpreter(),m_folder,m_selection,values());if(!execution.error.isEmpty()){m_status->setText(execution.error);return;}QMessageBox question(QMessageBox::Question,tr("Executar script"),tr("Executar o código exibido com suas permissões?\n\nPrograma: %1\nOrigem do código: %2\nSHA-256: %3\nPasta de trabalho: %4\n\nO script controla suas alterações; cancelar pode preservar resultados parciais.").arg(execution.interpreter,execution.sourcePath,QString::fromLatin1(execution.digest.toHex()),execution.folder),QMessageBox::Yes|QMessageBox::No,this);question.setObjectName("confirmUserScript");question.setDefaultButton(QMessageBox::No);question.setDetailedText(QString::fromUtf8(execution.input));if(question.exec()!=QMessageBox::Yes)return;m_permission->setChecked(false);m_output->clear();m_job=new UserScriptJob(execution,this);setBusy(true);m_status->setText(tr("Script em execução com as entradas revisadas…"));emit executionStarting();connect(m_job,&QThread::finished,this,[this]{m_job->wait();const auto result=m_job->result();m_output->setPlainText(result.output+(result.errors.isEmpty()?QString{}:tr("\n\nMensagens da ferramenta:\n")+result.errors));m_status->setText(result.message);m_job->deleteLater();m_job=nullptr;setBusy(false);if(m_closePending)QDialog::reject();});m_job->start();
}
void UserScriptDialog::reject(){if(m_job){m_closePending=true;m_job->cancel();m_status->setText(tr("Aguardando o encerramento antes de fechar…"));return;}QDialog::reject();}
